export function createLedger({ expectedAmounts = {} } = {}) {
  const entries = new Map();
  const handledIds = new Set();

  const knownTypes = new Set([
    "charge.success",
    "charge.failed",
    "charge.abandoned",
    "refund.processed",
  ]);

  const terminalChargeStatuses = new Set([
    "success",
    "partially_refunded",
    "refunded",
    "amount_mismatch",
  ]);

  function result(applied, reason, entry) {
    return {
      applied,
      reason,
      status: entry ? entry.status : null,
    };
  }

  function applyRefund(entry, amountKobo) {
    if (entry.status === "refunded") {
      return false;
    }

    const nextTotal = entry.refundedKobo + amountKobo;
    if (nextTotal > entry.amountKobo) {
      return false;
    }

    entry.refundedKobo = nextTotal;
    entry.status =
      nextTotal === entry.amountKobo ? "refunded" : "partially_refunded";
    return true;
  }

  return {
    handle(event) {
      if (!event || !knownTypes.has(event.type)) {
        return result(false, "unknown-type");
      }

      const { reference, id, type } = event;
      let entry = entries.get(reference);

      if (handledIds.has(id)) {
        return result(false, "duplicate", entry);
      }

      if (
        (type === "charge.success" || type === "refund.processed") &&
        (!Number.isInteger(event.amountKobo) || event.amountKobo <= 0)
      ) {
        return result(false, "invalid-amount", entry);
      }

      handledIds.add(id);

      if (!entry) {
        const hasExpectedAmount = Object.prototype.hasOwnProperty.call(
          expectedAmounts,
          reference
        );

        entry = {
          reference,
          status: "pending",
          amountKobo: hasExpectedAmount ? expectedAmounts[reference] : null,
          refundedKobo: 0,
          deferredRefunds: [],
        };
        entries.set(reference, entry);
      }

      if (type === "refund.processed") {
        if (entry.status === "amount_mismatch") {
          return result(false, "terminal", entry);
        }

        if (
          entry.status === "success" ||
          entry.status === "partially_refunded" ||
          entry.status === "refunded"
        ) {
          const applied = applyRefund(entry, event.amountKobo);
          return result(applied, applied ? null : "over-refund", entry);
        }

        entry.deferredRefunds.push(event.amountKobo);
        return result(false, "deferred", entry);
      }

      if (terminalChargeStatuses.has(entry.status)) {
        return result(false, "terminal", entry);
      }

      if (type === "charge.failed") {
        if (entry.status === "failed") {
          return result(false, "stale", entry);
        }

        entry.status = "failed";
        return result(true, null, entry);
      }

      if (type === "charge.abandoned") {
        if (entry.status !== "pending") {
          return result(false, "stale", entry);
        }

        entry.status = "abandoned";
        return result(true, null, entry);
      }

      const hasExpectedAmount = Object.prototype.hasOwnProperty.call(
        expectedAmounts,
        reference
      );
      const expectedAmount = hasExpectedAmount
        ? expectedAmounts[reference]
        : null;

      if (hasExpectedAmount && event.amountKobo !== expectedAmount) {
        entry.status = "amount_mismatch";
        entry.deferredRefunds.length = 0;
        return result(true, "amount-mismatch", entry);
      }

      entry.amountKobo = hasExpectedAmount ? expectedAmount : event.amountKobo;
      entry.status = "success";

      for (const amountKobo of entry.deferredRefunds) {
        applyRefund(entry, amountKobo);
      }
      entry.deferredRefunds.length = 0;

      return result(true, null, entry);
    },

    get(reference) {
      const entry = entries.get(reference);
      if (!entry) {
        return undefined;
      }

      return {
        reference: entry.reference,
        status: entry.status,
        amountKobo: entry.amountKobo,
        refundedKobo: entry.refundedKobo,
      };
    },
  };
}
